import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import PublicationReceipts from '../../../src/components/PublicationReceipts';import {stagedService} from '../../../src/lib/staged-service';import {publicationPayloadKey} from '../../../src/lib/editor-receipts-model';
export function SyntheticEditor(){const [g,setG]=useState({id:'synthetic-receipt',topic:'Synthetic topic',section:'Synthetic',source:'Synthetic publisher',type:'Synthetic',summary:'Synthetic fixture only',regionalVariation:false,localOverlayNeeded:false,lastChecked:'',status:'Drafted',versions:[{url:'https://synthetic.example.test/receipt',label:'Synthetic'}],sourceType:'national',guidanceStatus:'current'}),[selection,setSelection]=useState({ready:false,payloadKey:''}),[message,setMessage]=useState('');return <main><h1>Synthetic local editor</h1><label htmlFor="topic">Proposed topic</label><input id="topic" value={g.topic} onChange={e=>setG({...g,topic:e.target.value})}/><PublicationReceipts candidateId="00000000-0000-4000-8000-000000000099" guideline={g} enabled={true} onChange={setSelection}/><button disabled={!selection.ready||selection.payloadKey!==publicationPayloadKey(g)} onClick={async()=>{try{await stagedService.approve('00000000-0000-4000-8000-000000000099',g,'Synthetic publication only',selection);setMessage('Synthetic RPC confirmed');}catch(e){setMessage(String(e));}}}>Submit synthetic publication</button><p role="status">{message}</p></main>};createRoot(document.getElementById('root')).render(<SyntheticEditor/>);
